  function readBody(req) {
    return new Promise((resolve, reject) => {
      const chunks = []; let n = 0;
      req.on('data', c => { n += c.length; if (n > 10e6) { reject(new HttpError(400, 'validation_error', 'body too large')); req.destroy(); } else chunks.push(c); });
