  const w = 520, h = 220, pad = 30; const pts = r.burndown; const max = Math.max(1, ...pts.map(p => p.remainingPoints));
  const x = (n) => pad + (pts.length > 1 ? n * (w - 2 * pad) / (pts.length - 1) : 0), y = (v) => h - pad - v * (h - 2 * pad) / max;
